# Root-invoked bounded source mirror admission. It installs inputs, verifies them,
# verifies canonical binaries, invokes stager & preflight only, & starts no native work.
[CmdletBinding()]
param(
  [Parameter(Mandatory)][string]$ZipPath,
  [Parameter(Mandatory)][string]$RepositoryRoot,
  [Parameter(Mandatory)][string]$SourceManifestPath,
  [Parameter(Mandatory)][string]$InstallRoot,
  [Parameter(Mandatory)][string]$StageRoot,
  [Parameter(Mandatory)][string]$FactoryRoot,
  [Parameter(Mandatory)][string]$ControlRoot,
  [Parameter(Mandatory)][string]$Base,
  [Parameter(Mandatory)][string]$LockPath,
  [Parameter(Mandatory)][string]$WorkloadExe,
  [Parameter(Mandatory)][string]$RendererDll,
  [Parameter(Mandatory)][string]$PresentMonExe
)
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
$MaxFiles=256;$MaxFileBytes=[int64]8388608;$MaxTotalBytes=[int64]33554432;$MaxManifestBytes=[int64]1048576;$MaxHashBytes=[int64]67108864;$Chunk=65536
function Require([bool]$ok,[string]$message){if(-not $ok){throw $message}}
function Full([string]$path){return [IO.Path]::GetFullPath($path)}
function Under([string]$child,[string]$parent){$c=(Full $child).TrimEnd('\')+'\';$p=(Full $parent).TrimEnd('\')+'\';return $c.StartsWith($p,[StringComparison]::OrdinalIgnoreCase)}
function Require-Regular([string]$path,[int64]$maxBytes){$full=Full $path;Require (Test-Path -LiteralPath $full -PathType Leaf) "regular file missing: $full";$item=Get-Item -LiteralPath $full -Force;Require (($item.Attributes -band [IO.FileAttributes]::ReparsePoint)-eq 0) "reparse input rejected: $full";Require ($item.Length -le $maxBytes) "file exceeds bound: $full";return $item}
function Hash-File([string]$path,[int64]$maxBytes){$item=Require-Regular $path $maxBytes;$sha=[Security.Cryptography.SHA256]::Create();$stream=[IO.File]::Open($item.FullName,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);$buffer=New-Object byte[] $Chunk;$total=[int64]0;try{while(($n=$stream.Read($buffer,0,$buffer.Length))-gt 0){$total+=$n;Require ($total -le $maxBytes) "hash input exceeds bound: $path";$null=$sha.TransformBlock($buffer,0,$n,$buffer,0)}$null=$sha.TransformFinalBlock([byte[]]::new(0),0,0);return ([BitConverter]::ToString($sha.Hash)-replace '-','').ToLowerInvariant()}finally{$stream.Dispose();$sha.Dispose()}}
function Hash-Bytes([byte[]]$bytes){$sha=[Security.Cryptography.SHA256]::Create();try{$sha.ComputeHash($bytes)|Out-Null;return ([BitConverter]::ToString($sha.Hash)-replace '-','').ToLowerInvariant()}finally{$sha.Dispose()}}
function Read-ZipEntry([IO.Compression.ZipArchiveEntry]$entry,[int64]$maxBytes){$stream=$entry.Open();$memory=[IO.MemoryStream]::new();$buffer=New-Object byte[] $Chunk;$total=[int64]0;try{while(($n=$stream.Read($buffer,0,$buffer.Length))-gt 0){$total+=$n;Require ($total -le $maxBytes) "ZIP entry exceeds bound: $($entry.FullName)";$memory.Write($buffer,0,$n)}return $memory.ToArray()}finally{$memory.Dispose();$stream.Dispose()}}
function Hash-ZipEntry([IO.Compression.ZipArchiveEntry]$entry,[int64]$expectedBytes,[string]$expectedHash){$stream=$entry.Open();$sha=[Security.Cryptography.SHA256]::Create();$buffer=New-Object byte[] $Chunk;$total=[int64]0;try{while(($n=$stream.Read($buffer,0,$buffer.Length))-gt 0){$total+=$n;Require ($total -le $MaxFileBytes) "ZIP entry exceeds 8MiB: $($entry.FullName)";$null=$sha.TransformBlock($buffer,0,$n,$buffer,0)}$null=$sha.TransformFinalBlock([byte[]]::new(0),0,0);$actual=([BitConverter]::ToString($sha.Hash)-replace '-','').ToLowerInvariant();Require ($total -eq $expectedBytes -and $actual -ceq $expectedHash.ToLowerInvariant()) "ZIP entry hash/bytes mismatch: $($entry.FullName)";return $actual}finally{$stream.Dispose();$sha.Dispose()}}
function Write-Atomic([string]$path,[object]$value){Require (-not(Test-Path -LiteralPath $path)) "admission receipt must be fresh: $path";$parent=Split-Path -Parent (Full $path);if(-not(Test-Path -LiteralPath $parent)){[IO.Directory]::CreateDirectory($parent)|Out-Null};$tmp="$(Full $path).$PID.$([guid]::NewGuid().ToString('N')).tmp";$bytes=[Text.Encoding]::UTF8.GetBytes(($value|ConvertTo-Json -Depth 12)+"`r`n");$stream=[IO.File]::Open($tmp,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$stream.Write($bytes,0,$bytes.Length);$stream.Flush($true)}finally{$stream.Dispose()};[IO.File]::Move($tmp,(Full $path))}
$repo=Full $RepositoryRoot;$zipPath=Full $ZipPath;$sourceManifest=Full $SourceManifestPath;$install=Full $InstallRoot;$rootTools=Full (Join-Path $repo '.factory-work\root-tools');$expectedManifestSpecSha256='636d37daaadbba95120360f500f84ec955d6267811fcb2e23708349c6439dfd0';Require (Under $sourceManifest $repo) 'source manifest must remain under repository root';Require ((Hash-File $sourceManifest $MaxManifestBytes) -ceq $expectedManifestSpecSha256) 'source manifest canonical hash mismatch';Require (Under $install $rootTools) 'install root must remain under ignored root-tools';Require (-not(Test-Path -LiteralPath $install)) "fresh source mirror required: $install";$zipItem=Require-Regular $zipPath $MaxTotalBytes
Add-Type -AssemblyName System.IO.Compression.FileSystem
$zip=[IO.Compression.ZipFile]::OpenRead($zipPath);$manifestBytes=$null;$specInputBytes=$null;$entries=@{};$totalZipBytes=[int64]0
try{
  Require ($zip.Entries.Count -le $MaxFiles) 'ZIP entry count exceeds bound'
  foreach($entry in $zip.Entries){$name=[string]$entry.FullName;Require (-not $name.EndsWith('/')) "ZIP directory entry rejected: $name";Require (-not $name.Contains('\')) "ZIP path separator rejected: $name";Require (-not $name.StartsWith('/') -and $name -notmatch '(^|/)\.\.(/|$)' -and $name -notmatch '(^|/)\./') "ZIP traversal path rejected: $name";Require ((([int64]$entry.ExternalAttributes -shr 16) -band 0xF000) -ne 0xA000) "ZIP symlink entry rejected: $name";Require ([int64]$entry.Length -le $MaxFileBytes) "ZIP entry exceeds 8MiB: $name";$totalZipBytes+=[int64]$entry.Length;Require ($totalZipBytes -le $MaxTotalBytes) 'ZIP uncompressed total exceeds 32MiB';Require ($entries.ContainsKey($name)-eq $false) "duplicate ZIP entry: $name";$entries[$name]=$entry;if($name -ceq 'source-mirror-manifest.json'){$manifestBytes=Read-ZipEntry $entry $MaxManifestBytes};if($name -ceq 'source-mirror-spec-r10.json'){$specInputBytes=Read-ZipEntry $entry $MaxManifestBytes}}
  Require ($null -ne $manifestBytes -and $null -ne $specInputBytes) 'source mirror manifests missing';Require ((Hash-Bytes $specInputBytes) -ceq $expectedManifestSpecSha256) 'source mirror spec hash mismatch';$spec=([Text.Encoding]::UTF8.GetString($manifestBytes)|ConvertFrom-Json);Require ([string]$spec.schema -ceq 'sr0-display-selfjob-v4-source-mirror-r10') 'source mirror schema mismatch';Require ([string]$spec.manifestSpecSha256 -ceq $expectedManifestSpecSha256) 'source mirror input manifest hash mismatch';$manifestEntries=@($spec.entries);$toolSources=@($spec.toolSources);Require ($manifestEntries.Count -gt 0 -and $manifestEntries.Count -le ($MaxFiles-4)) 'source mirror entry count invalid';Require ($toolSources.Count -eq 2) 'source mirror admission source count invalid';Require ($entries.Count -eq ($manifestEntries.Count+$toolSources.Count+2)) 'ZIP contains unmanifested entries';$seen=@{};$manifestTotal=[int64]0
  foreach($record in $manifestEntries){$rel=[string]$record.path;Require (-not [string]::IsNullOrWhiteSpace($rel) -and -not $rel.Contains('\') -and -not $rel.StartsWith('/') -and $rel -notmatch '(^|/)\.\.(/|$)' -and $rel -notmatch '(^|/)\./') "manifest path unsafe: $rel";Require (-not $seen.ContainsKey($rel)) "manifest path duplicate: $rel";$seen[$rel]=$true;Require ($entries.ContainsKey($rel)) "manifest entry missing from ZIP: $rel";$bytes=[int64]$record.bytes;Require ($bytes -ge 0 -and $bytes -le $MaxFileBytes) "manifest byte bound invalid: $rel";$hash=[string]$record.sha256;Require ($hash -match '^[0-9a-fA-F]{64}$') "manifest hash invalid: $rel";$manifestTotal+=$bytes;Require ($manifestTotal -le $MaxTotalBytes) 'manifest source total exceeds 32MiB';Hash-ZipEntry $entries[$rel] $bytes $hash|Out-Null}
  $toolTotal=[int64]0;foreach($tool in $toolSources){$toolPath=[string]$tool.path;Require ($toolPath -in @('pack-source-mirror-r10.py','admit-source-mirror-r10.ps1')) "unexpected admission source: $toolPath";Require ($toolPath -notmatch '[\\/]' -and -not $toolPath.Contains('..')) "admission source path unsafe: $toolPath";Require ($entries.ContainsKey($toolPath)) "admission source missing: $toolPath";$toolBytes=[int64]$tool.bytes;$toolHash=[string]$tool.sha256;Require ($toolBytes -ge 0 -and $toolBytes -le $MaxFileBytes -and $toolHash -match '^[0-9a-fA-F]{64}$') "admission source metadata invalid: $toolPath";Hash-ZipEntry $entries[$toolPath] $toolBytes $toolHash|Out-Null;$toolTotal+=$toolBytes}
  Require ($manifestTotal + $toolTotal + [int64]$manifestBytes.Length + [int64]$specInputBytes.Length -le $MaxTotalBytes) 'source aggregate exceeds 32MiB including manifests/tools'
  if(-not(Test-Path -LiteralPath $install)){[IO.Directory]::CreateDirectory($install)|Out-Null}
  foreach($record in $manifestEntries){$rel=[string]$record.path;$destination=Full (Join-Path $install ($rel -replace '/','\'));Require (Under $destination $install) "mirror destination escapes root: $rel";$parent=Split-Path -Parent $destination;if(-not(Test-Path -LiteralPath $parent)){[IO.Directory]::CreateDirectory($parent)|Out-Null};Require (-not(Test-Path -LiteralPath $destination)) "mirror destination collision: $destination";$in=$entries[$rel].Open();$out=[IO.File]::Open($destination,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);$buffer=New-Object byte[] $Chunk;$copied=[int64]0;try{while(($n=$in.Read($buffer,0,$buffer.Length))-gt 0){$copied+=$n;Require ($copied -le $MaxFileBytes) "mirror extraction exceeds 8MiB: $rel";$out.Write($buffer,0,$n)}$out.Flush($true)}finally{$out.Dispose();$in.Dispose()};Require ($copied -eq [int64]$record.bytes) "mirror extraction byte mismatch: $rel"};foreach($support in @(@('source-mirror-manifest.json',$manifestBytes),@('source-mirror-spec-r10.json',$specInputBytes))){$destination=Full (Join-Path $install $support[0]);$out=[IO.File]::Open($destination,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$out.Write($support[1],0,$support[1].Length);$out.Flush($true)}finally{$out.Dispose()}};foreach($tool in $toolSources){$toolPath=[string]$tool.path;$destination=Full (Join-Path $install $toolPath);$out=[IO.File]::Open($destination,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);$in=$entries[$toolPath].Open();$buffer=New-Object byte[] $Chunk;try{while(($n=$in.Read($buffer,0,$buffer.Length))-gt 0){$out.Write($buffer,0,$n)}$out.Flush($true)}finally{$out.Dispose();$in.Dispose()}}
}finally{$zip.Dispose()}
$executableRecords=@($spec.executables);Require ($executableRecords.Count -eq 3) 'canonical executable record count mismatch';$executablePaths=@{workloadExe=(Full $WorkloadExe);rendererDll=(Full $RendererDll);presentMonExe=(Full $PresentMonExe)};$seenExecutableRoles=@{};foreach($record in $executableRecords){$role=[string]$record.role;Require ($executablePaths.ContainsKey($role)) "unexpected executable role: $role";Require (-not $seenExecutableRoles.ContainsKey($role)) "duplicate executable role: $role";$seenExecutableRoles[$role]=$true;$expected=[string]$record.sha256;Require ($expected -match '^[0-9a-fA-F]{64}$') "canonical executable hash invalid: $role";$actualPath=$executablePaths[$role];if($role -in @('workloadExe','rendererDll')){Require ([IO.Path]::GetFullPath((Join-Path $Base ([string]$record.relativePath))) -ceq $actualPath) "canonical executable path mismatch: $role"}else{Require ([IO.Path]::GetFullPath([string]$record.path) -ceq $actualPath) "canonical PresentMon path mismatch"};Require ((Hash-File $actualPath $MaxHashBytes) -ceq $expected.ToLowerInvariant()) "canonical executable hash mismatch: $role"};Require ($seenExecutableRoles.Count -eq $executablePaths.Count) 'canonical executable roles incomplete'
$stager=Full (Join-Path $install 'factory/pipeline/sr0-display-selfjob-v4/prospective-native-stage-v1/stage-prospective-native-r8.ps1');$preflight=Full (Join-Path $install 'factory/pipeline/sr0-display-selfjob-v4/prospective-native-stage-v1/entry-native-r8.ps1');Require (Test-Path -LiteralPath $stager -PathType Leaf) 'mirrored stager missing';Require (Test-Path -LiteralPath $preflight -PathType Leaf) 'mirrored preflight missing';Require (-not(Test-Path -LiteralPath (Join-Path $FactoryRoot 'source-mirror-admission-r10.json'))) 'admission receipt must be fresh';& $stager -RepositoryRoot $install -StageRoot $StageRoot -Base $Base -FactoryRoot $FactoryRoot -ControlRoot $ControlRoot -LockPath $LockPath;Require ($? -eq $true) 'mirrored stager failed';& $preflight -StageRoot $StageRoot;Require ($? -eq $true) 'mirrored preflight failed';$receipt=[ordered]@{kind='sr0-display-source-mirror-admission-r10';status='passed-source-admission';mirrorRoot=$install;mirrorZip=$zipPath;mirrorZipSha256=(Hash-File $zipPath $MaxTotalBytes);sourceFileCount=$manifestEntries.Count+$toolSources.Count+2;sourceBytes=$manifestTotal;toolBytes=$toolTotal;manifestBytes=([int64]$manifestBytes.Length+[int64]$specInputBytes.Length);archiveUncompressedBytes=$totalZipBytes;canonicalExecutables=$executableRecords;nativeActions=0;nativeQualificationClaim=$false};Write-Atomic (Join-Path $FactoryRoot 'source-mirror-admission-r10.json') $receipt;$receipt|ConvertTo-Json -Depth 8;exit 0
